def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [sign(tx - sx), sign(ty - sy)]

    def safe_pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def get_pos(obs, key, default=(0, 0)):
        return safe_pair(obs.get(key, default), default)

    def best_by(items, score_fn, pick_min=True):
        best_item = None
        best_score = None
        for item in items:
            try:
                score = score_fn(item)
            except Exception:
                continue
            if best_item is None or (pick_min and score < best_score) or ((not pick_min) and score > best_score):
                best_item = item
                best_score = score
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_pos(observation, "self_position")
    ox, oy = get_pos(observation, "opponent_position", (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = best_by(corners, lambda c: abs(c[0] - ox) + abs(c[1] - oy), pick_min=False)
        if target is None:
            target = (sx, sy)
        candidates = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                nx, ny = sx + dx, sy + dy
                dist = abs(nx - ox) + abs(ny - oy)
                edge = 0
                if gw:
                    edge += min(nx, max(0, gw - 1) - nx) if nx <= max(0, gw - 1) else 0
                if gh:
                    edge += min(ny, max(0, gh - 1) - ny) if ny <= max(0, gh - 1) else 0
                candidates.append((dx, dy, dist + abs(target[0] - nx) + abs(target[1] - ny) + edge))
        best = max(candidates, key=lambda t: t[2])
        return [best[0], best[1]]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        target = best_by(targets, lambda c: abs(c[0] - sx) + abs(c[1] - sy), pick_min=True)
        if target is not None:
            return step_toward(self_pos, safe_pair(target, self_pos))
        cx = observation.get("grid_width", 1)
        cy = observation.get("grid_height", 1)
        center = ((cx - 1) // 2 if cx else sx, (cy - 1) // 2 if cy else sy)
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by(resources, lambda c: abs(c[0] - sx) + abs(c[1] - sy), pick_min=True)
    if target is not None:
        return step_toward(self_pos, safe_pair(target, self_pos))

    return step_toward(self_pos, opp_pos)

